-- 178: Original BrillaPrep WASSCE BrillaPrep transitional Metalwork beta content blueprint questions, part 7.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_178_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_178_guard;
INSERT INTO _migration_178_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_031' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_7' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of the chuck on a centre lathe?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Hold the cutting tool at centre height","B. Feed coolant through every tool","C. Grip and rotate suitable workpieces about the spindle axis","D. Measure the taper angle directly"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The chuck transmits spindle torque while locating the work; safe gripping and removal of the chuck key are essential. Therefore the correct answer is C: Grip and rotate suitable workpieces about the spindle axis.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_7' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_031' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_178_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_032' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_7' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is a lathe cutting tool set close to centre height for ordinary turning?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Maximise tool overhang","B. Ensure the tool rubs below every surface","C. Make spindle speed independent of diameter","D. Maintain correct cutting geometry and avoid poor cutting or grabbing"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Incorrect height changes effective rake and clearance and can leave a pip, rub the work or create unsafe cutting forces. Therefore the correct answer is D: Maintain correct cutting geometry and avoid poor cutting or grabbing.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_7' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_032' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_178_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_033' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_7' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How should spindle speed generally change when drilling a larger diameter in the same material?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Decrease to keep cutting speed within a suitable range","B. Increase in direct proportion to diameter","C. Remain fixed for every drill size","D. Reverse continuously during cutting"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Cutting speed depends on tool circumference and revolutions, so a larger diameter normally requires fewer revolutions per minute. Therefore the correct answer is A: Decrease to keep cutting speed within a suitable range.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_7' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_033' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_178_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_034' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_7' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is feed in a machining operation?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The hardness of the cutting edge","B. The controlled advance of the cutting tool relative to the work","C. The electrical power rating of the machine","D. The diameter of the finished component"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Feed determines how far the cutting edge advances per revolution, stroke or tooth and influences load, finish and productivity. Therefore the correct answer is B: The controlled advance of the cutting tool relative to the work.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_7' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_034' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_178_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_035' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_7' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why must swarf be removed with a brush or hook rather than bare hands?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Swarf is always chemically poisonous","B. Hands reduce the machine speed automatically","C. Chips can be sharp, hot and entangled with the rotating work","D. A brush changes the alloy composition"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Machining chips readily cut skin and continuous swarf can catch and pull, so the machine is stopped and proper tools are used. Therefore the correct answer is C: Chips can be sharp, hot and entangled with the rotating work.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_7' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_035' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
